CREATE DATABASE IF NOT EXISTS trendsancr CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE trendsancr;
CREATE TABLE IF NOT EXISTS campaigns (id VARCHAR(64) PRIMARY KEY,name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS records (record_key VARCHAR(64) NOT NULL,campaign_id VARCHAR(64) NOT NULL,platform VARCHAR(32) NOT NULL,record_type VARCHAR(16) NOT NULL,published_at VARCHAR(32),collected_at VARCHAR(32),payload LONGTEXT NOT NULL,PRIMARY KEY(campaign_id,record_key));
CREATE TABLE IF NOT EXISTS imports (id VARCHAR(64) PRIMARY KEY,campaign_id VARCHAR(64) NOT NULL,created_at VARCHAR(32) NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS snapshot_runs (source VARCHAR(128) PRIMARY KEY,current_id VARCHAR(128),pending_id VARCHAR(128),phase VARCHAR(32));
CREATE TABLE IF NOT EXISTS snapshot_files (filename VARCHAR(160) PRIMARY KEY,csv_text LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS record_sources (campaign_id VARCHAR(64),record_key VARCHAR(64),source VARCHAR(255),payload LONGTEXT NOT NULL,PRIMARY KEY(campaign_id,record_key,source));
CREATE TABLE IF NOT EXISTS snapshot_attempts (source VARCHAR(128) PRIMARY KEY,submitted_at VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS campaign_identity (campaign_id VARCHAR(64) PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS team_accounts (id VARCHAR(64) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, role VARCHAR(24) NOT NULL, status VARCHAR(16) NOT NULL, password_hash VARCHAR(200));
CREATE TABLE IF NOT EXISTS keyword_rules (id VARCHAR(64) PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_versions (id VARCHAR(64) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS keyword_reviews (campaign_id VARCHAR(64) NOT NULL, record_key VARCHAR(64) NOT NULL, fingerprint VARCHAR(64) NOT NULL, decision VARCHAR(32) NOT NULL, PRIMARY KEY(campaign_id,record_key), FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS signal_reviews (id VARCHAR(64) PRIMARY KEY, campaign_id VARCHAR(64) NOT NULL, decision VARCHAR(32) NOT NULL, FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS processing_activity (id VARCHAR(64) PRIMARY KEY, created_at VARCHAR(32) NOT NULL, actor_id VARCHAR(64) NOT NULL, actor_name VARCHAR(160) NOT NULL, actor_role VARCHAR(24) NOT NULL, operation VARCHAR(100) NOT NULL, subject VARCHAR(255) NOT NULL, outcome VARCHAR(100) NOT NULL);

CREATE TABLE IF NOT EXISTS campaign_targets (id VARCHAR(64) PRIMARY KEY,name VARCHAR(255) NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS first_snapshot_inputs (source VARCHAR(128) PRIMARY KEY,dataset VARCHAR(128) NOT NULL,signature VARCHAR(64) NOT NULL);
CREATE TABLE IF NOT EXISTS snapshot_aliases (snapshot_id VARCHAR(128) PRIMARY KEY,source VARCHAR(128) NOT NULL);

CREATE TABLE IF NOT EXISTS collection_requests (source VARCHAR(128) PRIMARY KEY, period VARCHAR(8) NOT NULL, starts_at VARCHAR(32), ends_at VARCHAR(32) NOT NULL);

CREATE TABLE IF NOT EXISTS collected_snapshots (snapshot_id VARCHAR(128) PRIMARY KEY, period VARCHAR(8) NOT NULL, starts_at VARCHAR(32), ends_at VARCHAR(32), completed_at VARCHAR(32) NOT NULL);

CREATE TABLE IF NOT EXISTS disconnected_sources (source VARCHAR(128) PRIMARY KEY, campaign_id VARCHAR(64) NOT NULL);
